    heading: 'JSON path finder', intro: 'Find the exact path to a value in a large JSON document. Select a node in the tree to see its path, copy it with one click, or type a path to jump straight to the value.', modeLabel: 'Tree with paths', preset: { settings: { view: 'tree' }, initialText: store, initialFileName: 'store.json' }, sample: store, exampleLabel: 'Every value in the sample with the path that leads to it. Keys that are not plain names use brackets, such as ["first name"].', steps: ['Paste your JSON or open a file. The Tree view opens.', 'Click a value. Its path appears in the toolbar; click the path, or press P, to copy it.', 'To jump to a value, press Ctrl+F (⌘F) and type a path such as $.store.books[1].title, or a JSON Pointer such as /store/books/1/title.'], options: ['Paths use dot and bracket notation, as in JSONPath. Array indexes start at 0.', 'Find accepts a concrete path or a JSON Pointer (RFC 6901) and selects that node.', 'Wildcards, recursive descent, filters and slices, such as $..price, are not evaluated. The find bar says so instead of guessing.', 'Press C to copy the selected value. The More options menu also has Copy path and Copy value.'], faqs: [{ question: 'How do I find the JSON path of a value?', answer: 'Open the JSON in the Tree view and click the value. Its path appears in the toolbar, and clicking the path copies it.' }, { question: 'Can I search with a JSONPath expression?', answer: 'Concrete paths work, such as $.users[0].email. Expressions with wildcards or filters are not evaluated; search for a key or value with Find instead.' }, { question: 'Does it support JSON Pointer?', answer: 'Yes. Type a pointer such as /users/0/email in Find to jump to that value.' }], related: ['json-visualizer', 'json-flatten', 'large-json-viewer', 'jsonl-viewer', 'json-validator']
